/*
 * dAVEBOx SA launcher — the Tools-menu door asks first (Josh, 2026-09-30:
 * "Davebox launch from tool menu should show a confirmation message"; wording
 * ruled "Move will restart to load dAVEBOx. Proceed?" — it restarts Move, it
 * does not reboot the device).
 *
 * This runs inside STOCK Schwung's shadow UI as an ordinary interactive tool
 * (module.json: tool_config.skip_file_browser + interactive, NO `standalone`).
 * On Yes it runs exactly what stock ran for a standalone tool:
 * `sh launch-standalone.sh <module dir>/standalone`. On No it hands the screen
 * back with host_exit_module().
 *
 * ⚠ Why not `standalone: true` plus this screen: stock picks ONE launch path
 * per tool, and which one wins changed between versions — 1.5.0 tests
 * tool_config first, current upstream (tool_launch.mjs) makes `standalone`
 * win. Declaring only the interactive path behaves the same on both.
 *
 * ⭑ THE SCREENS ARE BITMAPS (Josh, 2026-10-09: "make the 'davebox will restart
 * move' dialog on launch from tools look better"). Stock has one 6px font and
 * none of dAVEBOx's faces, so asking in stock's overlay read as a different
 * app from the one it opens. The three screens below are drawn at build time
 * by dAVEBOx's own confirm chassis (davebox/tools/render_launcher_screens.mjs)
 * and blitted here, so the door looks like the room: the same header bar, body
 * face and Yes/No row as every dAVEBOx confirm, and the same wordmark screen
 * as the boot and exit ones.
 *
 * It behaves like those confirms too: the jog picks No or Yes, a click takes
 * the highlighted one, Back is No. ⚠ YES IS THE DEFAULT, unlike a destructive
 * confirm — choosing dAVEBOx in the Tools menu already said what was wanted,
 * so one click still launches, as it always has.
 *
 * ⚠ NO IMPORTS. A failed import is a Tools entry that cannot launch dAVEBOx at
 * all, on whatever stock this lands in. Only host globals are used, and if a
 * blit ever throws the screen falls back to plain text.
 */
const MODULE_DIR = '/data/UserData/schwung/modules/tools/davebox-sa';
const LAUNCH = 'sh /data/UserData/schwung/launch-standalone.sh ' + MODULE_DIR + '/standalone';

const CC_JOG_CLICK = 3;
const CC_JOG_TURN = 14;
const CC_BACK = 51;

/* 128x64, row-major, 8 px per byte, MSB = leftmost (the splash.hex contract). */
/* LAUNCH-FRAMES-BEGIN (generated: davebox/tools/render_launcher_screens.mjs --write) */
const FRAMES = {
    yes:
        '',
    no:
        '',
    starting:
        '',
};
/* LAUNCH-FRAMES-END */

/* Each frame as horizontal runs [x, y, w], decoded once: a screen is a few
 * hundred fill_rects a tick instead of thousands of pixels. */
const RUNS = {};
function runsOf(name) {
    if (RUNS[name]) return RUNS[name];
    const hex = FRAMES[name], runs = [];
    for (let y = 0; y < 64; y++) {
        let start = -1;
        for (let x = 0; x <= 128; x++) {
            const on = x < 128 &&
                ((parseInt(hex.substr((y * 16 + (x >> 3)) * 2, 2), 16) >> (7 - (x & 7))) & 1) === 1;
            if (on && start < 0) start = x;
            else if (!on && start >= 0) { runs.push([start, y, x - start]); start = -1; }
        }
    }
    return (RUNS[name] = runs);
}
function blit(name) {
    const runs = runsOf(name);
    for (let i = 0; i < runs.length; i++) fill_rect(runs[i][0], runs[i][1], runs[i][2], 1, 1);
}

let launching = false;
let selYes = true;

function draw() {
    clear_screen();
    try {
        blit(launching ? 'starting' : selYes ? 'yes' : 'no');
    } catch (e) {
        clear_screen();
        if (launching) { print(2, 28, 'Restarting Move...', 1); return; }
        print(2, 2, 'Load dAVEBOx?', 1);
        print(2, 18, 'Move will restart.', 1);
        print(2, 28, 'Proceed?', 1);
        print(2, 54, selYes ? 'No  [Yes]' : '[No]  Yes', 1);
    }
}

globalThis.init = function () {
    launching = false;
    selYes = true;
    draw();
};

globalThis.tick = function () {
    draw();
};

globalThis.onMidiMessageInternal = function (data) {
    if (!data || data.length < 3 || launching) return;
    if ((data[0] & 0xF0) !== 0xB0 || data[2] === 0) return;   /* CC presses and turns only */
    if (data[1] === CC_JOG_TURN) {
        selYes = data[2] < 64;            /* clockwise = Yes (right), back = No (left) */
        draw();
    } else if (data[1] === CC_JOG_CLICK) {
        if (!selYes) { host_exit_module(); return; }
        launching = true;
        draw();
        host_system_cmd(LAUNCH);
    } else if (data[1] === CC_BACK) {
        host_exit_module();
    }
};
